package com.primehr.operations;
import com.primehr.operations.domain.*;import org.junit.jupiter.api.Test;import java.time.*;import static org.assertj.core.api.Assertions.*;
class OperationsDomainTest {@Test void reconciliationFindingHasControlledLifecycle(){var f=new ReconciliationFinding("A","run",ReconciliationFinding.Kind.SOURCE_DRIFT,"TYPE","record","source",1L,"old",2L,"new","changed");f.acknowledge("reviewer",Instant.now());assertThat(f.getStatus()).isEqualTo(ReconciliationFinding.Status.ACKNOWLEDGED);f.resolve("reviewer","verified externally",Instant.now());assertThat(f.getStatus()).isEqualTo(ReconciliationFinding.Status.RESOLVED);assertThatThrownBy(()->f.acknowledge("reviewer",Instant.now())).isInstanceOf(IllegalStateException.class);}@Test void policyIsVersionedAndDateBound(){var p=new RetentionPolicyVersion("A","EVIDENCE",2,"TAG",365,LocalDate.of(2026,1,1),null,"Policy",true);assertThat(p.effectiveOn(LocalDate.of(2026,11,6))).isTrue();assertThat(p.effectiveOn(LocalDate.of(2025,12,31))).isFalse();}@Test void legalHoldCannotBeReleasedTwice(){var h=new LegalHold("A","EVIDENCE_ARTIFACT","id","case","REF","officer",Instant.now());h.release("officer","closed",Instant.now());assertThat(h.isActive()).isFalse();assertThatThrownBy(()->h.release("officer","again",Instant.now())).isInstanceOf(IllegalStateException.class);}}
